var busId = msg.payload.bus_id;
if (!busId) return null;

flow.set('gps_' + busId, { latitude: msg.payload.latitude, longitude: msg.payload.longitude, ts: Date.now() });

var speed = flow.get('speed_' + busId);
if (speed && (Date.now() - speed.ts) < 10000) {
    return { payload: { bus_id: busId, latitude: msg.payload.latitude, longitude: msg.payload.longitude, speed: speed.value } };
}
return null;

var busId = msg.payload.bus_id;
if (!busId) return null;

flow.set('speed_' + busId, { value: msg.payload.speed, ts: Date.now() });

var gps = flow.get('gps_' + busId);
if (gps && (Date.now() - gps.ts) < 10000) {
    return { payload: { bus_id: busId, latitude: gps.latitude, longitude: gps.longitude, speed: msg.payload.speed } };
}
return null;

msg.method  = 'POST';
msg.url     = 'http://gateway:3000/internal/traffic/location';
msg.headers = { 'Content-Type': 'application/json' };
node.log('Traffic → ' + JSON.stringify(msg.payload));
return msg;

if (msg.statusCode === 201) node.log('[Traffic OK] ' + JSON.stringify(msg.payload));
else node.warn('[Traffic ERROR] ' + msg.statusCode + ' ' + JSON.stringify(msg.payload));
return msg;

if (!msg.payload.bus_id || msg.payload.passenger_count === undefined) return null;
msg.method  = 'POST';
msg.url     = 'http://gateway:3000/internal/environment/passenger';
msg.headers = { 'Content-Type': 'application/json' };
node.log('Passenger → ' + JSON.stringify(msg.payload));
return msg;

if (!msg.payload.bus_id || msg.payload.temperature === undefined) return null;
msg.method  = 'POST';
msg.url     = 'http://gateway:3000/internal/environment/temperature';
msg.headers = { 'Content-Type': 'application/json' };
node.log('Temperature → ' + JSON.stringify(msg.payload));
return msg;

if (!msg.payload.bus_id || msg.payload.co2_ppm === undefined) return null;
msg.method  = 'POST';
msg.url     = 'http://gateway:3000/internal/environment/air';
msg.headers = { 'Content-Type': 'application/json' };
node.log('Air → ' + JSON.stringify(msg.payload));
return msg;

if (msg.statusCode === 201) node.log('[Env OK] ' + JSON.stringify(msg.payload));
else node.warn('[Env ERROR] ' + msg.statusCode + ' ' + JSON.stringify(msg.payload));
return msg;

// Validate required fields
var p = msg.payload;
if (!p.bus_id || p.speed === undefined || p.acceleration === undefined ||
    p.brake_force === undefined || p.turn_rate === undefined || p.vibration === undefined) {
    node.warn('Incomplete telemetry payload, skipping: ' + JSON.stringify(p));
    return null;
}
msg.method  = 'POST';
msg.url     = 'http://gateway:3000/internal/traffic/telemetry';
msg.headers = { 'Content-Type': 'application/json' };
node.log('Driver telemetry → bus_id=' + p.bus_id + ' speed=' + p.speed);
return msg;

if (msg.statusCode === 201) {
    node.log('[Driver OK] Telemetry saved, RabbitMQ event published');
} else {
    node.warn('[Driver ERROR] ' + msg.statusCode + ' ' + JSON.stringify(msg.payload));
}
return msg;
